#!/bin/bash\n\n# Nginx setup script for chatbot platform\n# This script helps configure and start the platform with nginx reverse proxy\n\nset -e\n\necho \"🚀 Setting up Chatbot Platform with Nginx\"\necho \"===========================================\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\n# Function to print colored output\nprint_status() {\n    echo -e \"${GREEN}[INFO]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARN]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Check if Docker and Docker Compose are installed\nif ! command -v docker &> /dev/null; then\n    print_error \"Docker is not installed. Please install Docker first.\"\n    exit 1\nfi\n\nif ! command -v docker-compose &> /dev/null; then\n    print_error \"Docker Compose is not installed. Please install Docker Compose first.\"\n    exit 1\nfi\n\n# Check if required files exist\nif [ ! -f \"docker-compose.yml\" ]; then\n    print_error \"docker-compose.yml not found in current directory\"\n    exit 1\nfi\n\nif [ ! -f \"nginx.conf\" ]; then\n    print_error \"nginx.conf not found in current directory\"\n    exit 1\nfi\n\n# Parse command line arguments\nENVIRONMENT=\"development\"\nSSL_ENABLED=false\n\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        --env)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --ssl)\n            SSL_ENABLED=true\n            shift\n            ;;\n        --help|-h)\n            echo \"Usage: $0 [OPTIONS]\"\n            echo \"Options:\"\n            echo \"  --env [development|production]  Set environment (default: development)\"\n            echo \"  --ssl                           Enable SSL/HTTPS (production only)\"\n            echo \"  --help, -h                      Show this help message\"\n            exit 0\n            ;;\n        *)\n            print_error \"Unknown option: $1\"\n            exit 1\n            ;;\n    esac\ndone\n\nprint_status \"Environment: $ENVIRONMENT\"\nprint_status \"SSL Enabled: $SSL_ENABLED\"\n\n# Setup environment file if it doesn't exist\nif [ ! -f \".env\" ]; then\n    print_warning \".env file not found, creating from template...\"\n    if [ -f \".env.template\" ]; then\n        cp .env.template .env\n        print_status \"Created .env from template. Please review and update values.\"\n    else\n        print_error \".env.template not found. Please create .env file manually.\"\n        exit 1\n    fi\nfi\n\n# Production-specific setup\nif [ \"$ENVIRONMENT\" = \"production\" ]; then\n    print_status \"Setting up production environment...\"\n    \n    if [ \"$SSL_ENABLED\" = true ]; then\n        print_status \"SSL/HTTPS is enabled\"\n        \n        # Check if SSL certificates exist\n        if [ ! -d \"ssl/certs\" ] || [ ! -d \"ssl/private\" ]; then\n            print_warning \"SSL directories not found. Creating...\"\n            mkdir -p ssl/certs ssl/private\n            chmod 700 ssl/private\n            \n            print_warning \"Please place your SSL certificates in:\"\n            print_warning \"  - ssl/certs/your-domain.crt\"\n            print_warning \"  - ssl/private/your-domain.key\"\n            print_warning \"And update the paths in nginx.prod.conf\"\n        fi\n        \n        # Use production nginx config\n        if [ -f \"nginx.prod.conf\" ]; then\n            print_status \"Using production nginx configuration\"\n            # We'll update docker-compose to use prod config\n        else\n            print_error \"nginx.prod.conf not found for production setup\"\n            exit 1\n        fi\n    fi\n    \n    # Setup monitoring credentials\n    if [ ! -f \"nginx/.htpasswd\" ]; then\n        print_warning \"Creating monitoring credentials...\"\n        mkdir -p nginx\n        echo \"Please set monitoring username and password:\"\n        read -p \"Username: \" username\n        if command -v htpasswd &> /dev/null; then\n            htpasswd -c nginx/.htpasswd \"$username\"\n        else\n            print_warning \"htpasswd not found. Please create nginx/.htpasswd manually\"\n        fi\n    fi\nfi\n\n# Choose the appropriate docker-compose command\nif [ \"$ENVIRONMENT\" = \"production\" ]; then\n    COMPOSE_CMD=\"docker-compose -f docker-compose.yml -f docker-compose.prod.yml -f docker-compose.nginx.yml\"\nelse\n    COMPOSE_CMD=\"docker-compose -f docker-compose.yml -f docker-compose.nginx.yml\"\nfi\n\nprint_status \"Starting services...\"\n\n# Pull latest images\nprint_status \"Pulling latest images...\"\n$COMPOSE_CMD pull\n\n# Build services\nprint_status \"Building services...\"\n$COMPOSE_CMD build\n\n# Start services\nprint_status \"Starting all services...\"\n$COMPOSE_CMD up -d\n\n# Wait a moment for services to start\nprint_status \"Waiting for services to start...\"\nsleep 10\n\n# Check service health\nprint_status \"Checking service health...\"\nif curl -s http://localhost/health > /dev/null; then\n    print_status \"✅ Platform is running successfully!\"\nelse\n    print_warning \"⚠️  Platform may still be starting up. Check logs if issues persist.\"\nfi\n\nprint_status \"Setup complete!\"\necho \"\"\necho \"📋 Service URLs:\"\necho \"   Admin Panel:    http://localhost/admin/\"\necho \"   API Gateway:    http://localhost/api/\"\necho \"   Web Chat:       http://localhost/chat/\"\necho \"   WhatsApp Hook:  http://localhost/webhook/whatsapp/\"\necho \"\"\necho \"📊 Monitoring:\"\necho \"   Health Check:   http://localhost/health\"\nif [ \"$ENVIRONMENT\" = \"production\" ]; then\n    echo \"   Metrics:        http://localhost/metrics (requires auth)\"\nfi\necho \"\"\necho \"🔧 Management Commands:\"\necho \"   View logs:      $COMPOSE_CMD logs -f\"\necho \"   Stop services:  $COMPOSE_CMD down\"\necho \"   Restart:        $COMPOSE_CMD restart\"\necho \"\"\n